/* Offline Chart.js Compatible Canvas Engine */
(function(global){
  function Chart(ctxOrCanvas, config){
    this.canvas = ctxOrCanvas && ctxOrCanvas.canvas ? ctxOrCanvas.canvas : ctxOrCanvas;
    this.ctx = this.canvas ? this.canvas.getContext('2d') : null;
    this.config = config || {};
    this.render();
  }
  Chart.prototype.destroy = function(){
    if(this.ctx && this.canvas){
      this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    }
  };
  Chart.prototype.render = function(){
    if(!this.canvas || !this.ctx) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const rect = this.canvas.getBoundingClientRect();
    const cssW = Math.max(280, rect.width || this.canvas.parentElement?.clientWidth || 340);
    const cssH = Math.max(170, rect.height || 200);
    this.canvas.width = cssW * dpr;
    this.canvas.height = cssH * dpr;
    const ctx = this.ctx;
    ctx.save();
    ctx.scale(dpr, dpr);
    ctx.clearRect(0, 0, cssW, cssH);

    const data = this.config.data || {};
    const labels = data.labels || [];
    const ds = (data.datasets && data.datasets[0]) || { data: [] };
    const values = (ds.data || []).map(v => Number(v) || 0);
    const isDay = document.body.classList.contains('day-mode');

    const padL = 44, padR = 14, padT = 22, padB = 34;
    const plotW = cssW - padL - padR;
    const plotH = cssH - padT - padB;
    const maxVal = Math.max(10, ...values) * 1.15;

    // Horizontal grid lines
    ctx.strokeStyle = isDay ? 'rgba(148,163,184,0.35)' : 'rgba(148,163,184,0.16)';
    ctx.fillStyle = isDay ? '#475569' : '#94a3b8';
    ctx.font = '10px monospace';
    ctx.textAlign = 'right';
    for(let g=0; g<=4; g++){
      const y = padT + (plotH * g / 4);
      const valLabel = Math.round(maxVal * (1 - g/4));
      ctx.beginPath(); ctx.moveTo(padL, y); ctx.lineTo(cssW - padR, y); ctx.stroke();
      ctx.fillText('$' + valLabel, padL - 6, y + 3);
    }

    const n = Math.max(1, labels.length);
    const slotW = plotW / n;
    const barW = Math.min(34, Math.max(12, slotW * 0.56));

    labels.forEach((lbl, idx) => {
      const val = values[idx] || 0;
      const barH = (val / maxVal) * plotH;
      const x = padL + idx * slotW + (slotW - barW) / 2;
      const y = padT + plotH - barH;

      const grad = ctx.createLinearGradient(0, y, 0, padT + plotH);
      grad.addColorStop(0, '#38bdf8');
      grad.addColorStop(1, '#0284c7');
      ctx.fillStyle = grad;
      ctx.beginPath();
      const r = Math.min(6, barW / 2, barH);
      if(barH > 0){
        ctx.roundRect ? ctx.roundRect(x, y, barW, barH, [r, r, 0, 0]) : ctx.rect(x, y, barW, barH);
        ctx.fill();
      }

      // Value above bar
      if(val > 0){
        ctx.fillStyle = isDay ? '#0369a1' : '#7dd3fc';
        ctx.font = 'bold 10px monospace';
        ctx.textAlign = 'center';
        ctx.fillText('$' + val.toFixed(0), x + barW/2, Math.max(12, y - 4));
      }

      // X-axis label
      ctx.fillStyle = isDay ? '#334155' : '#cbd5e1';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(String(lbl), x + barW/2, cssH - 12);
    });

    ctx.restore();
  };
  global.Chart = Chart;
})(window);
